import{Message}from"./message.js";import{isMessage}from"./is-message.js";export function toPlainMessage(message){if(!isMessage(message))return message;const type=message.getType(),target={};for(const member of type.fields.byMember()){const source=message[member.localName];let copy;if(member.repeated)copy=source.map(e=>toPlainValue(e));else if("map"==member.kind){copy={};for(const[key,v]of Object.entries(source))copy[key]=toPlainValue(v)}else if("oneof"==member.kind){copy=member.findField(source.case)?{case:source.case,value:toPlainValue(source.value)}:{case:void 0}}else copy=toPlainValue(source);target[member.localName]=copy}return target}function toPlainValue(value){if(void 0===value)return value;if(isMessage(value))return toPlainMessage(value);if(value instanceof Uint8Array){const c=new Uint8Array(value.byteLength);return c.set(value),c}return value}